    ('booking.reschedule_cap','Maximum moves per booking','Other','bookings','booking','number','5'::jsonb,'Further moves require cancelling and making a new booking.','supabase/migrations/20261113125512_bookings.sql#L483'),
    -- rule-policy: technical audited-reference Copies source facts into reference records with no effect on workflow behavior.
    ('booking.reminder_hours','Booking reminder lead time','Other','bookings','booking','hours','24'::jsonb,'Reminder for the booker is queued this far before the appointment.','supabase/migrations/20261113125512_bookings.sql#L199'),
    ('support.ticket_priority_default','New support ticket priority default','Communications','support_tickets','ticket','text','"Normal"'::jsonb,'Applied when a new ticket has no explicit priority.','supabase/migrations/20261112021616_support_tickets.sql#L24'),
    -- rule-policy: technical audited-reference Copies source facts into reference records with no effect on workflow behavior.
    ('support.ticket_reply_status_moves','Support ticket status changes on reply','Communications','support_tickets','ticket','json','{"staff":{"open":"waiting","in_progress":"waiting"},"requester":{"waiting":"open","resolved":"open"}}'::jsonb,'The two reply paths change ticket state as shown.','supabase/migrations/20261112021616_support_tickets.sql#L218'),
    ('support.ticket_attachment_limit_mib','Support ticket attachment limit (MiB)','Communications','support_tickets','ticket','number','10'::jsonb,'Existing file size cap in the support ticket upload flow.','src/lib/supportTickets.ts#L60'),
    -- rule-policy: technical audited-reference Copies source facts into reference records with no effect on workflow behavior.
    ('cms.navigation_label_char_cap','Website navigation label character limit','CMS Website','navigation','navigation','number','22'::jsonb,'Existing label length in the navigation editor and validator.','src/config/cmsLimits.ts#L5'),
    ('cms.footer_label_char_cap','Footer link label character limit','CMS Website','footer','footer','number','30'::jsonb,'Existing label length in the website footer editor and validator.','src/config/cmsLimits.ts#L4'),
    -- rule-policy: technical audited-reference Copies source facts into reference records with no effect on workflow behavior.
    ('cms.cms_document_limit_mib','CMS website document upload limit (MiB)','CMS Website','documents','document','number','20'::jsonb,'Existing website document storage client limit.','src/pages/admin/lib/storage.ts#L6'),
    ('office365.student_license_fallback','Microsoft 365 student licence fallback','Communications','email_management/create','mailbox','text','"Office 365 A1 for students"'::jsonb,'Fallback licence mapping when no student SKU is set in integration configuration.','supabase/functions/_shared/office365-provision.ts#L35'),
    -- rule-policy: technical audited-reference Copies source facts into reference records with no effect on workflow behavior.
    ('office365.staff_license_fallback','Microsoft 365 staff and agent licence fallback','Communications','email_management/create','mailbox','text','"Office 365 A1 for faculty"'::jsonb,'Fallback licence mapping when no staff SKU is set in integration configuration.','supabase/functions/_shared/office365-provision.ts#L39')
  ) as x(identifier, label, category, menu_id, entity, value_type, value, notes, source) loop
    insert into public.business_rules(scope_key,identifier,registration)
      values ('',item.identifier,jsonb_build_object('scope',item.menu_id,'entity',item.entity,'value_type',item.value_type,
        'schema_version',1,'handler','inventory_only')) on conflict (scope_key,identifier) do nothing returning id into rule_id;
    if rule_id is null then continue; end if;

    -- Labels may have been renamed. Reuse the matching category if present and
    -- otherwise use a category already owned by the same institution.
    -- rule-policy: technical category-lookup Chooses an existing category if the original category label was renamed.
    select c.id into category from public.business_rule_categories c where c.scope_key = ''
      order by (c.name = item.category) desc, (c.name = 'Other') desc, c.id limit 1;
    if category is null then raise exception 'Load Skyline Business Rules categories before importing the inventory'; end if;
    d := jsonb_build_object(
      'name',item.label,'identifier',item.identifier,'category_id',category,
      'scope',item.menu_id,'entity',item.entity,'description',item.notes,
      'value_type',item.value_type,'value',item.value,'options','[]'::jsonb,'groups','[]'::jsonb,'match','all',
      'then_action','use_value','else_action','none','priority',0,'starts_on',added_on,'ends_on','',
      'enabled',false,'approval_required',false,'source_url',source_base || item.source,
      'notes','Source audit reference. The workflow continues to use its current implementation or stored configuration.');
    perform public.business_rule_validate(d, null);
    insert into public.business_rule_versions(rule_id,version,state,origin,definition,starts_on)
      values (rule_id,1,'reference','migration',d,added_on) returning id into version_id;
    perform public.business_rule_index_version(version_id,d);
    insert into public.business_rule_audit_logs(scope_key,rule_id,action,reason,after_data)
      values ('',rule_id,'migration','Catalogued existing behavior for SLIT review.',d);
  end loop;
end $$;

